mapper.select:
SELECT id, title, detail, category, priority, due_date, completed, completed_at, pinned, created_at, updated_at FROM todos
deleted_at IS NULL
title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND due_date >= #{from, jdbcType=DATE}
AND due_date <= #{to, jdbcType=DATE}
ORDER BY pinned DESC, due_date
DESC ASC

SELECT id, title, detail, category, priority, due_date, completed, completed_at, pinned, created_at, updated_at FROM todos
deleted_at IS NULL AND due_date IS NOT NULL
AND due_date >= #{from, jdbcType=DATE}
AND due_date <= #{to, jdbcType=DATE}
ORDER BY due_date ASC
